export function quarterEnds(introducedAt,through){const start=koreaDate(new Date(introducedAt)),end=koreaDate(new Date(through)),out=[];for(let y=Number(start.slice(0,4));y<=Number(end.slice(0,4));y++)for(const[quarter,day]of [[1,'03-31'],[2,'06-30'],[3,'09-30'],[4,'12-31']]){const date=y+'-'+day;if(date>=start&&date<=end)out.push({quarterKey:y+'-Q'+quarter,dueDate:date});}return out;}
